#!/bin/sh
set -eu

ziran=$1
tools=$(dirname "$ziran")
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT HUP INT TERM

# `ziran build -o DIR` owns DIR: generated files an earlier build left there
# (for example under a module name that has since changed) are removed so a
# `DIR/*.c` link cannot pick up dead copies. Other files are kept.
cat > "$work/app.zi" <<'ZI'
#program_export
Answer :: () -> s32 { return 42 }
ZI

check_target() {
    target=$1
    marker=$2
    extension=$3
    output="$work/$target"
    mkdir -p "$output"
    printf '%s old.zi. */\n' "$marker" > "$output/old.$extension"
    printf 'kept by the user\n' > "$output/notes.$extension"
    "$ziran" build --target="$target" --root "$work" -o "$output" \
        "$work/app.zi"
    if test -e "$output/old.$extension"; then
        echo "$target build kept a stale generated file" >&2
        exit 1
    fi
    test -f "$output/notes.$extension"
    test -f "$output/app.$extension"
}
check_target c '/* Generated by zi2c from' c
check_target go '// Code generated by zi2go from' go

# Running a backend directly still accumulates, so several invocations can
# share one directory.
mkdir -p "$work/shared"
printf '/* Generated by zi2c from other.zi. */\n' > "$work/shared/other.c"
"$tools/zi2c" --no-main --root "$work" -o "$work/shared" "$work/app.zi"
test -f "$work/shared/other.c"

# Many inputs lower on emission workers. Their output, including files in
# package subdirectories, matches one serial worker byte for byte, and
# --prune-stale also cleans those subdirectories.
mkdir -p "$work/many/pkg"
i=0
while test $i -lt 40; do
    printf 'Value%d :: () -> s32 { return %d }\n' $i $i > "$work/many/pkg/m$i.zi"
    i=$((i + 1))
done
mkdir -p "$work/parallel/pkg" "$work/serial"
printf '/* Generated by zi2c from gone.zi. */\n' > "$work/parallel/pkg/gone.c"
printf 'kept by the user\n' > "$work/parallel/pkg/notes.c"
(cd "$work/many" && "$tools/zi2c" --no-main --prune-stale --root . -o "$work/parallel" pkg/*.zi)
(cd "$work/many" && ZIRAN_JOBS=1 "$tools/zi2c" --no-main --root . -o "$work/serial" pkg/*.zi)
if test -e "$work/parallel/pkg/gone.c"; then
    echo 'zi2c --prune-stale kept a stale generated file in a subdirectory' >&2
    exit 1
fi
test -f "$work/parallel/pkg/notes.c"
rm "$work/parallel/pkg/notes.c"
diff -r -x .build.lock "$work/serial" "$work/parallel"
test -f "$work/parallel/pkg/m39.c"
echo 'stale generated output: C, Go pruned; direct backends accumulate; workers match serial'
